                    "max_chars": {
                        "type": "integer",
                        "description": "Maximum characters to return from text artifacts.",
                        "minimum": 1,
                        "maximum": 100000,
                        "default": 50000,
                    },
                },
                "required": ["artifact"],
                "additionalProperties": False,
            },
        },
    ]

